package org.eclipse.rdf4j.http.server.repository.statements;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.nio.charset.StandardCharsets;

import org.eclipse.rdf4j.http.protocol.Protocol;
import org.eclipse.rdf4j.http.server.ClientHTTPException;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.memory.MemoryStore;
import org.junit.jupiter.api.Test;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpServletResponse;

class BlankNodeReferenceHttpUpdateAtomicityTest {
	@Test
	void malformedMultiOperationRequestWritesNothingThroughTheRealStatementsHandler() throws Exception {
		String update = "INSERT DATA { <urn:partial> <urn:p> <urn:o> }; "
				+ "INSERT DATA { _:reused <urn:p> <urn:o> }; "
				+ "DELETE DATA { _:reused <urn:p> <urn:o> }";
		SailRepository repository = new SailRepository(new MemoryStore());
		repository.init();
		try {
			MockHttpServletRequest request = new MockHttpServletRequest();
			request.setMethod("POST");
			request.setContentType(Protocol.SPARQL_UPDATE_MIME_TYPE);
			request.setContent(update.getBytes(StandardCharsets.UTF_8));
			request.setAttribute("repository", repository);
			request.setAttribute("repositoryID", "blank-node-reference-update-atomicity");

			assertThrows(ClientHTTPException.class,
					() -> new StatementsController().handleRequest(request, new MockHttpServletResponse()));
			try (var connection = repository.getConnection()) {
				assertEquals(0, connection.size(),
						"a statically invalid later operation must prevent every operation from writing");
			}
		} finally {
			repository.shutDown();
		}
	}
}
